import { parseRoute } from './navigation.js';
import type { FeedbackPreferences, Journey, RouteDocument, Target } from './types.js';

export function routeDocument(targets: Target[], journey: Pick<Journey, 'name' | 'sequence'>): RouteDocument {
  return {
    points: targets.map(({ id, latitude, longitude, radiusMeters }) => ({ id, latitude, longitude, radiusMeters })),
    journey: { name: journey.name, sequence: [...journey.sequence] }
  };
}

export function routeSignature(targets: Target[], journey: Journey) {
  return JSON.stringify(routeDocument(targets, journey));
}

// Storage is optional. A blocked/quota-limited store must not stop navigation.
export function createJourneyStore(storage: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>, scope: string) {
  const prefix = `geo-map:${scope}:`;
  const failures = new Set();
  function read(key: string): unknown {
    try { return JSON.parse(storage.getItem(prefix + key) || 'null'); }
    catch { failures.add(key); return null; }
  }
  function write(key: string, value: unknown) {
    try { storage.setItem(prefix + key, JSON.stringify(value)); failures.delete(key); return true; }
    catch { failures.add(key); return false; }
  }
  return {
    get available() { return failures.size === 0; },
    saveProgress(targets: Target[], journey: Journey) {
      return write('progress', { version: 1, signature: routeSignature(targets, journey),
        activeStepIndex: journey.activeStepIndex, awaitingExit: journey.awaitingExit });
    },
    restoreProgress(targets: Target[], journey: Journey) {
      const saved = read('progress') as { version?: number; signature?: string; activeStepIndex?: number; awaitingExit?: boolean } | null;
      if (saved?.version !== 1 || saved.signature !== routeSignature(targets, journey) ||
          saved.activeStepIndex == null || !Number.isInteger(saved.activeStepIndex) || saved.activeStepIndex < 0 || saved.activeStepIndex > journey.sequence.length ||
          typeof saved.awaitingExit !== 'boolean') return false;
      journey.activeStepIndex = saved.activeStepIndex;
      journey.awaitingExit = saved.awaitingExit;
      journey.paused = true;
      return true;
    },
    loadRoute() {
      const data = read('route');
      if (!data) return null;
      try { const route = parseRoute(data); return routeDocument(route.targets, route.journey); } catch { return null; }
    },
    saveRoute(data: RouteDocument) { parseRoute(data); return write('route', data); },
    clearRoute() {
      try { storage.removeItem(prefix + 'route'); failures.delete('route'); return true; } catch { failures.add('route'); return false; }
    },
    loadPreferences() {
      const data = read('preferences') as Partial<FeedbackPreferences> | null;
      return { sound: data?.sound === true, haptics: data?.haptics === true };
    },
    savePreferences(preferences: FeedbackPreferences) { return write('preferences', preferences); }
  };
}
